【决策】删掉 effective_to，选纯追加模型：唯一约束 (tenant_id,currency,effective_from)；某时点价 = effective_from<=t 中最大者；上界由后继行推导；不再需要 EXCLUDE/btree_gist；改价=新行+supersedes_id，REVOKE UPDATE,DELETE 才成立。限时价若将来需要，再走列级授权 GRANT UPDATE(effective_to)+触发器，不在本期。
【DDL v2】
CREATE TABLE erp.metering_price_book (
  id uuid PRIMARY KEY,
  tenant_id uuid NOT NULL,
  currency char(3) NOT NULL DEFAULT 'CNY',
  unit_label text NOT NULL DEFAULT '供应商对账单行',
  unit_price numeric(18,4) NOT NULL CHECK (unit_price > 0),
  effective_from timestamptz NOT NULL,
  contract_ref text NOT NULL CHECK (length(btrim(contract_ref)) > 0),
  approved_by_user_id uuid NOT NULL,
  approved_at timestamptz NOT NULL,
  supersedes_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_price_book_id_tenant UNIQUE (id, tenant_id),
  CONSTRAINT fk_price_book_supersedes FOREIGN KEY (supersedes_id, tenant_id) REFERENCES erp.metering_price_book (id, tenant_id),
  CONSTRAINT ck_price_book_no_self_supersede CHECK (supersedes_id IS NULL OR supersedes_id <> id)
);
CREATE UNIQUE INDEX uq_price_book_tenant_currency_from ON erp.metering_price_book (tenant_id, currency, effective_from);
ALTER TABLE erp.recon_batch ADD COLUMN unit_price numeric(18,4);
ALTER TABLE erp.recon_batch ADD COLUMN currency char(3);
ALTER TABLE erp.recon_batch ADD COLUMN unit_price_source text;
ALTER TABLE erp.recon_batch ADD COLUMN price_book_id uuid;
ALTER TABLE erp.recon_batch ADD CONSTRAINT fk_recon_batch_price_book FOREIGN KEY (price_book_id, tenant_id) REFERENCES erp.metering_price_book (id, tenant_id);
ALTER TABLE erp.recon_batch ADD CONSTRAINT ck_recon_batch_price_snapshot CHECK (unit_price_source IS NULL OR (unit_price_source='missing' AND unit_price IS NULL AND price_book_id IS NULL) OR (unit_price_source='env_fallback' AND unit_price IS NOT NULL AND price_book_id IS NULL AND currency IS NOT NULL) OR (unit_price_source IN ('snapshot','lookback') AND unit_price IS NOT NULL AND price_book_id IS NOT NULL AND currency IS NOT NULL));
REVOKE ALL ON erp.metering_price_book FROM erp_app;
GRANT SELECT, INSERT ON erp.metering_price_book TO erp_app;
【六处】①supersedes 复合 FK + 防自指；顺带补 recon_batch.price_book_id 的复合 FK（同一类跨租户洞）；②recon_batch 补 currency/unit_price_source 及来源-金额-价目行一致性 CHECK；③唯一索引列序含 currency，DESC 查询走反向扫描，不再加重复 DESC 索引；④金额规则：4 位小数精确存储，只在出账时一次 ROUND_HALF_UP 到 2 位（算例 0.3333×3=0.9999→1.00；逐行舍入会得 0.99），Python 必须显式 HALF_UP；⑤approved_by_user_id uuid NOT NULL，仓库无 users 表（0003 created_by 同约定），若有身份表再补复合 FK，插价目行必须同事务写审计事件；⑥表由 erp_migrator 创建，建表后显式 REVOKE（ALTER DEFAULT PRIVILEGES 会自动授 UPDATE/DELETE），必带负向用例：erp_app 执行 UPDATE 价目行必须权限错误。
